 P(id="iv-1248", level="M", title="Ровно k нечётных", leetcode=1248,
   statement="Верни число непрерывных подмассивов nums, содержащих ровно k нечётных чисел.",
   fn="number_of_subarrays", starter="def number_of_subarrays(nums, k):\n    pass\n",
   clarify=[("Какой размер nums?", "До 5·10⁴.", True), ("Может ли k быть больше числа нечётных?", "Да — тогда ответ 0.", True),
            ("Подмассив непрерывный?", "Да.", False), ("Числа положительные?", "Да.", False)],
   brute=dict(options=["Перебрать все отрезки, считая нечётные", "Отсортировать", "Перебрать подмножества"], answer=0, t="O(n²)"),
   tech=dict(options=["не больше k − не больше k − 1 (окно)", "Одно окно «ровно k»", "Два указателя с концов", "Куча"], answer=0, t="O(n)", m="O(1)"),
   tests=[dict(args=[[1, 1, 2, 1, 1], 3], exp=2), dict(args=[[2, 4, 6], 1], exp=0), dict(args=[[2, 2, 2, 1, 2, 2, 1, 2, 2, 2], 2], exp=16, hidden=True, case="чётные по краям"),
          dict(args=[[1], 1], exp=1, hidden=True, case="один элемент")],
   speed=dict(gen="import random\nrandom.seed(14)\nARGS=[[random.randint(1,4) for _ in range(50000)], 100]"),
   ref="def number_of_subarrays(nums, k):\n    def at_most(k):\n        if k < 0:\n            return 0\n        odd = l = res = 0\n        for r, x in enumerate(nums):\n            odd += x % 2\n            while odd > k:\n                odd -= nums[l] % 2\n                l += 1\n            res += r - l + 1\n        return res\n    return at_most(k) - at_most(k - 1)\n",
   bad=["def number_of_subarrays(nums, k):\n    res = 0\n    for i in range(len(nums)):\n        odd = 0\n        for j in range(i, len(nums)):\n            odd += nums[j] % 2\n            if odd == k:\n                res += 1\n    return res\n"],
   hints=["«Ровно k» не монотонно — одно окно не подойдёт.", "«Не больше k» монотонно.", "Ровно k = (не больше k) − (не больше k − 1).", "at_most(k): окно, while нечётных > k; res += r − l + 1.", "Два прохода окна — O(n)."],
   expl="Приём «ровно = не больше k − не больше k − 1»: два окна, O(n)."),
